/*
 * PION/1 -- 1-bit sine table.
 *
 * The table itself is generated by tools/gen_sine_table.py and lives in
 * sine_table.c.  This header exposes the lookup helpers.
 *
 * Geometry
 * --------
 *   quarter cycle : 2048 bits (64 words)
 *   full cycle    : 8192 bits (256 words)
 *   base frequency: fs / 8192  ->  61.04 Hz at fs = 500 kHz
 *
 * Phase convention
 * ----------------
 * A phase is a 32-bit accumulator where the top 13 bits select the bit
 * position within the 8192-bit cycle:
 *
 *   a = ph >> 19            (0 .. 8191)
 *
 * Quadrature is free: adding 0x40000000 advances a quarter cycle, and
 * adding 0x80000000 inverts the waveform.
 */
#ifndef PION1_SINE_TABLE_H
#define PION1_SINE_TABLE_H

#include <stdint.h>

#define PION1_SINE_QUARTER_BITS 2048u
#define PION1_SINE_QUARTER_WORDS 64u
#define PION1_SINE_FULL_BITS 8192u
#define PION1_SINE_FULL_WORDS 256u

/* Phase increment for a given frequency, for a given sample rate.
 * step = f_hz * (2^32 / fs). */
#define PION1_PHASE_STEP(f_hz, fs) \
    ((uint32_t)((double)(f_hz) * 4294967296.0 / (double)(fs)))

extern const uint32_t pion1_sine_quarter[PION1_SINE_QUARTER_WORDS];
extern const uint32_t pion1_sine_full[PION1_SINE_FULL_WORDS];

/*
 * Read one bit of the full sine cycle.
 *
 * The quarter table is mirrored and inverted for the second half of the
 * cycle; the mirroring is done with a whole-word fetch plus a bit-reverse
 * table rather than per-bit work.
 */
static inline uint32_t pion1_sine_bit(uint32_t ph)
{
    uint32_t a = ph >> 19;             /* 0 .. 8191, bit position in cycle */
    uint32_t i = a & (PION1_SINE_QUARTER_BITS - 1u);

    if (a & PION1_SINE_QUARTER_BITS) {
        /* Quadrants 1 and 3: the quarter table runs backwards. */
        i = (PION1_SINE_QUARTER_BITS - 1u) - i;
    }

    {
        uint32_t b = (pion1_sine_quarter[i >> 5] >> (i & 31u)) & 1u;
        /* Quadrants 2 and 3 are inverted. */
        return b ^ (a >> 12);
    }
}

/* Read the quarter-sine table bit at index i (0 .. 2047). */
static inline uint32_t pion1_sine_quarter_bit(uint32_t i)
{
    return (pion1_sine_quarter[i >> 5] >> (i & 31u)) & 1u;
}

#endif /* PION1_SINE_TABLE_H */
